    (x = e^{lambda/2}, lambda = kappa t the rapidity) has inverse (x + 1/x)/2 - (x - 1/x)/2 sigma, scales
    the ladder operators f = (e+ + e-)/2, f* = (e+ - e-)/2 by x^{-2} and x^2, that is e^{-+kappa t}, and obeys
    R(x) R(y) = R(xy) (the flow is a one-parameter group, amplitudes grow as e^{kappa t}). In Cl(2,2) (two
    modes) the common boost R_1(x) R_2(x) scales all four ladder operators with the same factors: one
    rapidity for every mode.
(2) Threshold: an amplitude 1/N carried by the flow reaches 1 exactly when e^{kappa t} = x^2 = N (checked
    at N = 4, 9, 25, 49 with x^2 = N, and strictly below 1 at the previous integer x), so
    t_* = kappa^{-1} ln N; with ln N a formal logarithm (LogVec) and N = S, t_* = 4M ln S.
(3) Rates: kappa = f'(2M)/2 = 1/(4M) from f = 1 - 2M/r (exact rational functions, several M), so
    beta = 2 pi/kappa = 8 pi M, beta/(2 pi) = 1/kappa = 4M, and the expansion rate kappa equals 2 pi T
    with T = 1/beta (pi formal).
"""
from fractions import Fraction as F

import GA
import series
from tp_premise import premise

# --- formal logarithms: a LogVec is a finite rational combination sum_p a_p ln p over primes, so
# entropies of rational spectra are exact LogVecs; inequalities are decided by rigorous rational
# bounds on ln p (ln p = a ln 2 + 2 atanh z, atanh summed with an explicit geometric tail bound) ---

def factorise(n):
    out = {}
    d = 2
    while d * d <= n:
        while n % d == 0:
            out[d] = out.get(d, 0) + 1
            n //= d
        d += 1 if d == 2 else 2
    if n > 1:
        out[n] = out.get(n, 0) + 1
    return out


class LogVec(object):
    def __init__(self, d=None):
        self.d = {p: F(c) for p, c in (d or {}).items() if c != 0}

    @staticmethod
    def ln_int(n):
        return LogVec({p: e for p, e in factorise(n).items()})

    @staticmethod
    def ln_rat(q):
        q = F(q)
        assert q > 0
        return LogVec.ln_int(q.numerator) - LogVec.ln_int(q.denominator)

    def __add__(self, o):
        d = dict(self.d)
        for p, c in o.d.items():
            d[p] = d.get(p, F(0)) + c
        return LogVec(d)

    def __neg__(self):
        return LogVec({p: -c for p, c in self.d.items()})

    def __sub__(self, o):
        return self + (-o)

    def __mul__(self, c):
        return LogVec({p: v * F(c) for p, v in self.d.items()})

    __rmul__ = __mul__

    def __eq__(self, o):
        return self.d == o.d

    def __ne__(self, o):
        return not self.__eq__(o)


_LNB = {}
def ln_bounds(n):
    """Rational (lower, upper) bounds on ln n, n a positive integer (series.ln_bounds, cached)."""
    if n not in _LNB:
        _LNB[n] = series.ln_bounds(n)
    return _LNB[n]


def logvec_bounds(v):
    lo, hi = F(0), F(0)
    for p, c in v.d.items():
        a, b = ln_bounds(p)
        if c > 0:
            lo += c * a
            hi += c * b
        else:
            lo += c * b
            hi += c * a
    return lo, hi


def logvec_lt(u, v):
    """u < v, decided rigorously; equal vectors give False."""
    if u == v:
        return False
    lo, hi = logvec_bounds(v - u)
    if lo > 0:
        return True
    if hi < 0:
        return False
    raise ValueError("bounds too weak")


def logvec_le(u, v):
    return u == v or logvec_lt(u, v)


def entropy(probs):
    """-sum p ln p of a rational spectrum, as a LogVec (nats)."""
    out = LogVec()
    for p in probs:
        if p != 0:
            assert p > 0
            out = out - LogVec.ln_rat(p) * p
    return out

SQ11 = (1, -1)
SQ22 = (1, 1, -1, -1)
XS = [F(2), F(3, 2), F(5), F(1, 3)]
NS = [4, 9, 25, 49]
MASSES = [F(1), F(3, 2), F(7)]


def rotor(x, plus, minus, sq):
    sig = GA.mul(GA.gen(plus), GA.gen(minus), sq)
    ch, sh = (x + 1 / x) / 2, (x - 1 / x) / 2
    return GA.add(GA.sc(ch), GA.scal(sh, sig)), GA.sub(GA.sc(ch), GA.scal(sh, sig)), sig


def ladders(plus, minus):
    f = GA.scal(F(1, 2), GA.add(GA.gen(plus), GA.gen(minus)))
    fs = GA.scal(F(1, 2), GA.sub(GA.gen(plus), GA.gen(minus)))
    return f, fs


def check_boost_flow_scales_ladders_exponentially():
    premise("scrambling.imported-modes-modular-inventory")
    premise("scrambling.clock-inventory-boundary-modes")
    f, fs = ladders(0, 1)
    for x in XS:
        R, Rinv, sig = rotor(x, 0, 1, SQ11)
        assert GA.eq(GA.mul(sig, sig, SQ11), GA.sc(1))
        assert GA.eq(GA.mul(R, Rinv, SQ11), GA.sc(1))
        assert GA.eq(GA.mul(GA.mul(R, f, SQ11), Rinv, SQ11), GA.scal(1 / (x * x), f))
        assert GA.eq(GA.mul(GA.mul(R, fs, SQ11), Rinv, SQ11), GA.scal(x * x, fs))
        for y in XS:
            Ry = rotor(y, 0, 1, SQ11)[0]
            assert GA.eq(GA.mul(R, Ry, SQ11), rotor(x * y, 0, 1, SQ11)[0])
    # two modes in Cl(2,2): e+_1 = e0, e+_2 = e1, e-_1 = e2, e-_2 = e3; the common boost
    for x in XS[:2]:
        R1, R1i, _ = rotor(x, 0, 2, SQ22)
        R2, R2i, _ = rotor(x, 1, 3, SQ22)
        R, Ri = GA.mul(R1, R2, SQ22), GA.mul(R2i, R1i, SQ22)
        assert GA.eq(GA.mul(R, Ri, SQ22), GA.sc(1))
        for (p, m) in ((0, 2), (1, 3)):
            g, gs = ladders(p, m)
            assert GA.eq(GA.mul(GA.mul(R, g, SQ22), Ri, SQ22), GA.scal(1 / (x * x), g))
            assert GA.eq(GA.mul(GA.mul(R, gs, SQ22), Ri, SQ22), GA.scal(x * x, gs))


iroot = series.isqrt


def check_spreading_threshold_is_log_n():
    premise("scrambling.area-law-test")
    f, fs = ladders(0, 1)
    for N in NS:
        x = F(iroot(N))
        assert x * x == N
        R, Rinv, _ = rotor(x, 0, 1, SQ11)
        grown = GA.mul(GA.mul(R, GA.scal(F(1, N), fs), SQ11), Rinv, SQ11)
        assert GA.eq(grown, fs)                              # amplitude 1/N grown to 1
        Rb, Rbinv, _ = rotor(x - 1, 0, 1, SQ11)
        early = GA.mul(GA.mul(Rb, GA.scal(F(1, N), fs), SQ11), Rbinv, SQ11)
        coef = early[(0,)] * 2
        assert 0 < coef < 1
    for M in MASSES:
        kappa_inv = 4 * M
        for N in NS:
            t_star = LogVec.ln_int(N) * kappa_inv          # kappa t_* = ln N
            assert t_star * (1 / kappa_inv) == LogVec.ln_int(N)
            assert t_star == LogVec.ln_int(iroot(N)) * (8 * M)


def check_rate_is_modular_rate():
    premise("scrambling.mode-count")
    r = GA.RF.var()
    for M in MASSES:
        f = GA.RF1 - GA.RF.const(2 * M) / r
        kappa = f.deriv().eval(2 * M) / 2
        assert kappa == 1 / (4 * M)
        beta_over_pi = 2 / kappa                              # beta = 2 pi / kappa
        assert beta_over_pi == 8 * M
        assert beta_over_pi / 2 == 1 / kappa == 4 * M
        T_times_pi = 1 / beta_over_pi                         # pi T = 1/(beta/pi)
        assert kappa == 2 * T_times_pi

scrambling.uniqueness-internal-scaling:
"""scrambling.uniqueness-internal-scaling: exact checks of the scaling test.

Dimensional quantities are exact monomials c * 2^a * 3^b * pi^p * M^e with rational c and rational
exponents (factors 2 and 3 folded into the exponents, so equal quantities have equal representations);
every scaling statement is an identity of exponents. Units G = c = hbar = 1.
(1) The framework's cutoff: 2M/r^3 = 1 gives r_c = (2M)^{1/3}, and the slice volume per unit Killing time
    4 pi r_c^2 sqrt(2M/r_c) is exactly 8 pi M (p = 1). The Kretschmann cutoff 48 M^2/r^6 = 1 and the
    unit-proper-time cutoff give radii 2^{2/3} 3^{1/6} M^{1/3} and 3^{2/3} 2^{-1/3} M^{1/3}: the same
    M-exponent 1/3 and the same p = 1, with order-one coefficients.
(2) Alternatives: the sphere-only count 4 pi r_c^2 has exponent 2/3 and the fixed-radius volume
    4 pi r_0^2 sqrt(2M/r_0) has exponent 1/2, so with Delta t of order M they give M^{5/3} and M^{3/2};
    the area law M^2 then needs q = 4/3 and q = 3/2, outside the admissible set {1, 3} (a logarithmic
    dressing multiplies by ln M and changes no exponent). Over all computed schemes, p = 1 is the only
    exponent with 2 - p admissible, and it needs q = 1, an order-M timescale.
"""
from fractions import Fraction as F

import GA
from tp_premise import premise


class Mono(object):
    __slots__ = ("c", "a", "b", "p", "e")

    def __init__(self, c=1, a=0, b=0, p=0, e=0):
        c, a, b = F(c), F(a), F(b)
        if c != 0:
            n, d = c.numerator, c.denominator
            while n % 2 == 0:
                n //= 2
                a += 1
            while d % 2 == 0:
                d //= 2
                a -= 1
            while n % 3 == 0:
                n //= 3
                b += 1
            while d % 3 == 0:
                d //= 3
                b -= 1
            c = F(n, d)
        self.c, self.a, self.b, self.p, self.e = c, a, b, F(p), F(e)

    def __mul__(self, o):
        return Mono(self.c * o.c, self.a + o.a, self.b + o.b, self.p + o.p, self.e + o.e)

    def __truediv__(self, o):
        return Mono(self.c / o.c, self.a - o.a, self.b - o.b, self.p - o.p, self.e - o.e)

    def pow(self, q):
        q = F(q)
        assert self.c == 1
        return Mono(1, self.a * q, self.b * q, self.p * q, self.e * q)

    def __eq__(self, o):
        return (self.c, self.a, self.b, self.p, self.e) == (o.c, o.a, o.b, o.p, o.e)


M = Mono(e=1)
PI = Mono(p=1)
TWO = Mono(a=1)
THREE = Mono(b=1)
R0 = Mono(1, -2, 2)                        # a mass-independent cutoff radius, 9/4
ADMISSIBLE = (F(1), F(3))                  # Delta t ~ M (crossing, epoch, modular) and ~ M^3 (lifetime)


def num(x):
    return Mono(c=x)


def slice_volume(r):
    return num(4) * PI * r * r * (TWO * M / r).pow(F(1, 2))


def check_internal_cutoff_gives_linear_volume():
    premise("scrambling.slice-volume-exactly-per-unit-killing")
    r_c = (TWO * M).pow(F(1, 3))
    assert r_c * r_c * r_c == TWO * M
    assert slice_volume(r_c) == num(8) * PI * M
    r_k = (TWO.pow(4) * THREE * M * M).pow(F(1, 6))
    assert r_k == Mono(1, F(2, 3), F(1, 6), 0, F(1, 3))
    assert (r_k * r_k * r_k) * (r_k * r_k * r_k) == num(48) * M * M
    r_t = (THREE / TWO).pow(F(2, 3)) * (TWO * M).pow(F(1, 3))
    assert r_t == Mono(1, F(-1, 3), F(2, 3), 0, F(1, 3))
    # (2/3) r^{3/2} (2M)^{-1/2} = 1 at r_t
    assert num(F(2, 3)) * r_t.pow(F(3, 2)) * (TWO * M).pow(F(-1, 2)) == num(1)
    for r in (r_c, r_k, r_t):
        assert r.e == F(1, 3) and slice_volume(r).e == 1


def check_alternatives_fail_and_p_one_is_unique():
    r_c = (TWO * M).pow(F(1, 3))
    sphere = num(4) * PI * r_c * r_c
    fixed = slice_volume(R0)
    internal = slice_volume(r_c)
    assert sphere.e == F(2, 3) and fixed.e == F(1, 2) and internal.e == 1
    order_M = M
    assert (sphere * order_M).e == F(5, 3) and (fixed * order_M).e == F(3, 2)
    assert (internal * order_M).e == 2
    needed = {s: F(2) - v.e for s, v in (("sphere", sphere), ("fixed", fixed), ("internal", internal))}
    assert needed == {"sphere": F(4, 3), "fixed": F(3, 2), "internal": F(1)}
    working = [s for s, q in needed.items() if q in ADMISSIBLE]
    assert working == ["internal"] and needed["internal"] == ADMISSIBLE[0]
    lifetime_p = F(2) - ADMISSIBLE[1]
    assert lifetime_p == -1 and lifetime_p not in [v.e for v in (sphere, fixed, internal)]
